"""Explicit tenant graph policy. Import is pure; inspection is verification only.

A6 is a foundation, not endpoint integration. No function here executes writes.
The catalog is reviewed source data, never populated from live ORM reflection.
"""
from dataclasses import dataclass
from types import MappingProxyType

ERROR_CODE = "TENANT_RELATION_CONFLICT"
GLOBAL_ROLES = frozenset(("super_admin", "staff_admin", "staff_operator"))
BRANCH_ROLES = frozenset(("branch_manager", "operator"))
ROLES = GLOBAL_ROLES | BRANCH_ROLES | frozenset(("client", "client_admin", "client_operator"))


def conflict():
    from fastapi import HTTPException
    return HTTPException(status_code=409, detail=ERROR_CODE)


