def model_spec(name):
    if type(name) is not str or name not in MODELS:
        raise conflict()
    return MODELS[name]


def relation_spec(key):
    if type(key) is not str or key not in RELATIONS:
        raise conflict()
    return RELATIONS[key]


def model_class(name):
    model_spec(name)
    from app.models import entities
    cls = getattr(entities, name, None)
    if cls is None or cls.__name__ != name:
        raise conflict()
    return cls


def relations_for(name):
    model_spec(name)
    return tuple(r for r in RELATION_SPECS if r.model == name)


def inspect_registry():
    """No connection, engine, or writes; compare metadata with reviewed source."""
    from sqlalchemy import inspect
    from app.models import entities  # noqa: F401
    from app.models.base import Base
    models, edges, columns, orm = set(), set(), {}, {}
    table_names = {m.local_table.name: m.class_.__name__ for m in Base.registry.mappers}
    for mapper in Base.registry.mappers:
        name = mapper.class_.__name__
        models.add((name, mapper.local_table.name))
        columns[name] = tuple(p.key for p in mapper.column_attrs)
        orm[name] = tuple(
            (r.key, r.mapper.class_.__name__, str(r.cascade), r.passive_deletes,
             r.direction.name, tuple(sorted(c.key for c in r.local_columns)),
             tuple(sorted(c.key for c in r.remote_side)))
            for r in inspect(mapper.class_).relationships
        )
        for fk in mapper.local_table.foreign_keys:
            target = table_names.get(fk.column.table.name)
            edges.add((name, fk.parent.key, target, fk.parent.nullable, fk.ondelete))
    return models, edges, columns, orm


