# A6-R1 audio-chain requirement: playlist integrity includes its registered items.
# These are explicit reverse dependencies, not arbitrary ORM backrefs.
COLLECTION_DEPENDENCIES = ("AudioPlaylistItem.playlist_id", "VideowallPublicationAsset.publication_id", "VideowallPlaybackGroupMember.group_id")


def relation_fingerprint(edge):
    from dataclasses import fields
    from hashlib import sha256
    import json
    values = {f.name: getattr(edge, f.name) for f in fields(RelationSpec)}
    values["operations"] = sorted(values["operations"])
    values["exclusions"] = sorted(values["exclusions"])
    return sha256(json.dumps(values, sort_keys=True, separators=(",", ":"), ensure_ascii=True).encode()).hexdigest()


def inspect_orm_delete_orphans():
    """ORM inventory, independent of FK on-delete and owner policy inventories."""
    from sqlalchemy import inspect
    return tuple(sorted(
        (spec.name, rel.key, rel.mapper.class_.__name__, str(rel.cascade))
        for spec in MODEL_SPECS for rel in inspect(model_class(spec.name)).relationships
        if "delete-orphan" in rel.cascade
    ))


def inspect_relation_orm_effect(edge):
    """Associate an inverse relationship by its concrete FK, never class pair."""
    from sqlalchemy import inspect
    source = model_class(edge.model)
    fk = inspect(source).columns[edge.field]
    effects = []
    for rel in inspect(model_class(edge.target)).relationships:
        if rel.mapper.class_ is source and fk in rel._calculated_foreign_keys:
            effects.append(f"{edge.target}.{rel.key}: {rel.cascade}; passive_deletes={str(rel.passive_deletes).lower()}")
    return " | ".join(effects) or "Sin relationship inversa ORM; la FK de DB sigue aplicando"


def validate_registry(snapshot=None):
    """Reject drift instead of deriving permissions or delete actions from it."""
    fingerprints = {e.key: relation_fingerprint(e) for e in RELATION_SPECS}
    if (fingerprints != dict(APPROVED_RELATION_FINGERPRINTS)
            or dict(RELATIONS) != {e.key: e for e in RELATION_SPECS}
            or dict(MODELS) != {s.name: s for s in MODEL_SPECS}
            or COLLECTION_DEPENDENCIES != ("AudioPlaylistItem.playlist_id", "VideowallPublicationAsset.publication_id", "VideowallPlaybackGroupMember.group_id")):
        raise conflict()
    if len(MODELS) != len(MODEL_SPECS) or len(RELATIONS) != len(RELATION_SPECS):
        raise conflict()
    for spec in MODEL_SPECS:
        visited = set()
        cursor = spec
        while cursor.owner_kind != "root":
            if cursor.name in visited or cursor.owner_target not in MODELS:
                raise conflict()
            visited.add(cursor.name)
            edge = relation_spec(cursor.name + "." + str(cursor.owner_field))
            if edge.target != cursor.owner_target or edge.owner_kind != cursor.owner_kind:
                raise conflict()
            cursor = MODELS[cursor.owner_target]
        if cursor.name != "Client":
            raise conflict()
    for edge in RELATION_SPECS:
        if (edge.model not in MODELS or edge.target not in MODELS
                or edge.field not in MODELS[edge.model].columns
                or edge.owner_kind not in {"context", "direct-owner", "structural-owner"}
                or edge.operations | frozenset(k for k, _ in edge.exclusions)
                != {"READ", "WRITE", "DELETE", "RUNTIME"}
                or edge.operations & frozenset(k for k, _ in edge.exclusions)):
            raise conflict()
    expected = (
        {(s.name, s.table) for s in MODEL_SPECS},
        {(r.model, r.field, r.target, r.nullable, r.on_delete) for r in RELATION_SPECS},
        {s.name: s.columns for s in MODEL_SPECS},
        {s.name: s.orm_relationships for s in MODEL_SPECS},
    )
    if (inspect_registry() if snapshot is None else snapshot) != expected:
        raise conflict()
    if any(edge.orm_cascade != inspect_relation_orm_effect(edge) for edge in RELATION_SPECS):
        raise conflict()
    if len({(o.method, o.path) for o in OPERATIONS}) != len(OPERATIONS):
        raise conflict()
    return True
